package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;
/** Native4 operation sync. Never replaces the local DB; absence is never a delete. */
public final class Native4SyncEngine{
 public interface Transport{Ack push(Op op)throws Retryable,Permanent;}public static final class Ack{public final long revision;public Ack(long r){revision=r;}}public static final class Op{public final String id,kind,recordId,payload,deviceId;Op(String i,String k,String r,String p,String d){id=i;kind=k;recordId=r;payload=p;deviceId=d;}}public static final class Retryable extends Exception{public Retryable(String m){super(m);}}public static final class Permanent extends Exception{public Permanent(String m){super(m);}}
 private final CoreDb db;private final Transport transport;public Native4SyncEngine(CoreDb d,Transport t){if(d==null||t==null)throw new IllegalArgumentException("Sync dependencies مطلوبة");db=d;transport=t;}
 public interface Progress{void onOperation(String kind,String recordId,String payload,int index,int total);}
 public synchronized Result pushPending(){return pushPending(null);}
 public synchronized Result pushPending(Progress progress){recoverStaleSending();int ok=0,retries=0,failed=0;for(int page=0;page<20;page++){List<Op> operations=pending();if(operations.isEmpty())break;int index=0;for(Op op:operations){index++;if(retries>0||failed>0)break;if(!claim(op.id))continue;try{if(progress!=null){try{progress.onOperation(op.kind,op.recordId,op.payload,index,operations.size());}catch(RuntimeException callbackError){android.util.Log.w("Native4Sync","Progress callback failed; upload continues",callbackError);}}Ack a=transport.push(op);if(a==null||a.revision<=0)throw new IllegalStateException("Firestore returned an invalid confirmation revision");confirm(op.id,a.revision);ok++;}catch(Retryable e){retry(op.id,e.getMessage());retries++;}catch(Permanent e){failClaimed(op.id,e.getMessage());failed++;}catch(RuntimeException e){retry(op.id,"تعذر الإرسال: "+e.getClass().getSimpleName());retries++;}}if(operations.size()<100||retries>0||failed>0)break;}return new Result(ok,retries,failed);}
 private boolean claim(String id){ContentValues v=new ContentValues();v.put("state","SENDING");v.put("last_attempt_at",System.currentTimeMillis());return db.db().update("outbox",v,"operation_id=? AND state IN ('PENDING','RETRY')",new String[]{id})==1;}
 private void recoverStaleSending(){ContentValues v=new ContentValues();v.put("state","RETRY");long cutoff=System.currentTimeMillis()-120000L;db.db().update("outbox",v,"state='SENDING' AND (last_attempt_at IS NULL OR last_attempt_at<?)",new String[]{String.valueOf(cutoff)});}
 private List<Op> pending(){ArrayList<Op> x=new ArrayList<>();try(Cursor c=db.db().rawQuery("SELECT operation_id,operation_kind,record_id,payload,source_device_id FROM outbox WHERE state IN ('PENDING','RETRY') ORDER BY created_at,operation_id LIMIT 100",null)){while(c.moveToNext())x.add(new Op(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4)));}return x;}
 private void confirm(String id,long rev){SQLiteDatabase s=db.db();s.beginTransaction();try{ContentValues v=new ContentValues();v.put("state","CONFIRMED");v.put("confirmed_revision",rev);v.putNull("last_error");if(s.update("outbox",v,"operation_id=? AND state='SENDING'",new String[]{id})!=1)throw new IllegalStateException("Sync confirmation lost claimed operation");ContentValues a=new ContentValues();a.put("operation_id",id);a.put("applied_at",System.currentTimeMillis());s.insertWithOnConflict("applied",null,a,SQLiteDatabase.CONFLICT_IGNORE);s.setTransactionSuccessful();}finally{s.endTransaction();}}
 private void retry(String id,String e){ContentValues v=new ContentValues();v.put("state","RETRY");v.put("last_attempt_at",System.currentTimeMillis());v.put("last_error",e);SQLiteDatabase s=db.db();s.beginTransaction();try{s.execSQL("UPDATE outbox SET attempts=attempts+1 WHERE operation_id=? AND state='SENDING'",new Object[]{id});if(s.update("outbox",v,"operation_id=? AND state='SENDING'",new String[]{id})!=1)throw new IllegalStateException("Retry operation state changed unexpectedly");s.setTransactionSuccessful();}finally{s.endTransaction();}}private void failClaimed(String id,String error){ContentValues v=new ContentValues();v.put("state","FAILED");v.put("last_attempt_at",System.currentTimeMillis());v.put("last_error",error);if(db.db().update("outbox",v,"operation_id=? AND state='SENDING'",new String[]{id})!=1)throw new IllegalStateException("Failed operation state changed unexpectedly");}
 public static final class Result{public final int confirmed,retries,failed;Result(int c,int r,int f){confirmed=c;retries=r;failed=f;}}
}
